using WypozyczalniaSportowa.Domain.Contracts;
using WypozyczalniaSportowa.Domain.Exceptions;
using WypozyczalniaSportowa.Domain.Pricing;
namespace WypozyczalniaSportowa.Domain;

public abstract class Equipment : Entity, IReservable, IIdentifiable, ICloneableEntity<Equipment>, IComparable<Equipment>, IEquatable<Equipment> { private string _name = ""; private decimal _dailyRate; private bool _available = true; protected Equipment(string name, decimal rate) { Name = name; DailyRate = rate; } protected Equipment(int id, string name, decimal rate, bool available) : base(id) { Name = name; DailyRate = rate; _available = available; } public string Name { get => _name; private set => _name = string.IsNullOrWhiteSpace(value) ? throw new DomainValidationException("Nazwa jest wymagana.") : value.Trim(); } public decimal DailyRate { get => _dailyRate; private set => _dailyRate = value <= 0 ? throw new DomainValidationException("Cena dobowa musi być dodatnia.") : value; } public bool IsAvailable => _available; public abstract string Kind { get; } public abstract int Detail { get; } public abstract decimal CalculateRentalPrice(RentalPeriod period, IPricingStrategy strategy); public void Reserve() { if (!_available) throw new EquipmentUnavailableException(Id); _available = false; } public void Release() { if (_available) throw new DomainValidationException("Sprzęt nie jest wypożyczony."); _available = true; } internal void RestoreAvailability(bool available) => _available = available; public int CompareTo(Equipment? x) => x is null ? 1 : DailyRate.CompareTo(x.DailyRate); public bool Equals(Equipment? x) => x is not null && Id == x.Id; public override bool Equals(object? o) => o is Equipment x && Equals(x); public override int GetHashCode() => Id.GetHashCode(); public abstract Equipment CloneEntity(bool deep); public override Entity Clone(bool deep) => CloneEntity(deep); public override string ToString() => $"{Kind} #{Id}: {Name}, {DailyRate:C}/dzień, {(IsAvailable ? "dostępny" : "niedostępny")}"; }
